/* All assets and computation stay on this device. */
const G=GeoMath;let scenario='gradual',engine=new G.Engine(Math.random,scenario),running=false,page='Overview',drawerKind=null,compare=false,snapshot=null,selectedTime=null,rotation=0,zoom=1,matrixTab='Matrix',matrixState='Current',rawMode=false,selectedSignals=[0,1,2,3,6],networkMode='Current',locked=false,eqStep=-1,eqTimer=null,previousFocus=null,drag=null;
const pages=['Overview','Geometry','Research','System Architecture','Impact','About'];
const paths=['M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z','M2 12h5l3-8 4 16 3-8h5','m12 2 10 6v9l-10 5L2 17V8Zm0 0v20M2 8l10 6 10-6','M4 3v18M12 3v18M20 3v18M3 4h18M3 12h18M3 20h18','M4 3h12l4 4v14H4Zm4 6h8M8 13h8M8 17h5','M8 3h8v6H8zM3 16h6v5H3zM15 16h6v5h-6zM12 9v4H6v3m6-3h6v3','m3 17 6-6 4 3 8-10M15 4h6v6','M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'];
// Preserve live nodes, focus and animations across one-second state updates.
function mount(markup){const template=document.createElement('template');template.innerHTML=markup;function sync(parent,source){const incoming=[...source.childNodes];for(let i=0;i<incoming.length;i++){const fresh=incoming[i],old=parent.childNodes[i];if(!old){parent.appendChild(fresh.cloneNode(true));continue;}if(old.nodeType!==fresh.nodeType||old.nodeName!==fresh.nodeName){parent.replaceChild(fresh.cloneNode(true),old);continue;}if(old.nodeType===Node.TEXT_NODE){if(old.nodeValue!==fresh.nodeValue)old.nodeValue=fresh.nodeValue;continue;}if(old.nodeType!==Node.ELEMENT_NODE)continue;for(const attr of [...old.attributes])if(!fresh.hasAttribute(attr.name))old.removeAttribute(attr.name);for(const attr of [...fresh.attributes])if(old.getAttribute(attr.name)!==attr.value){if(attr.name==='points'&&old.classList.contains('current-shape')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){morph(old,attr.value);}else old.setAttribute(attr.name,attr.value);}sync(old,fresh);}while(parent.childNodes.length>incoming.length)parent.lastChild.remove();}sync(document.getElementById('app'),template.content);}
function morph(node,target){if(node._frame)cancelAnimationFrame(node._frame);const from=node.getAttribute('points').split(/[ ,]+/).map(Number),to=target.split(/[ ,]+/).map(Number);if(from.length!==to.length){node.setAttribute('points',target);return;}const start=performance.now();function frame(now){if(!node.isConnected)return;const t=Math.min(1,(now-start)/600),ease=1-(1-t)**3;node.setAttribute('points',from.map((v,i)=>v+(to[i]-v)*ease).reduce((s,v,i)=>s+(i%2?',':' ')+v,'').trim());if(t<1)node._frame=requestAnimationFrame(frame);else node._frame=null;}node._frame=requestAnimationFrame(frame);}
const icon=(i,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[i]}"/></svg>`;
const f=(x,n=2)=>Number(x).toFixed(n),time=t=>`${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const tag=(s,cls='')=>`<span class="tag ${cls}">${s}</span>`;
function panel(title,sub,body,actions='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${actions}</div>${body}</section>`;}
function controls(){const opts=[['healthy','HEALTHY / STABLE'],['gradual','GRADUAL DETERIORATION'],['rapid','RAPID DETERIORATION'],['noisy','NOISY BUT STABLE']];return `<div class="scenario-control"><label>SIMULATION SCENARIO</label><div class="segmented">${opts.map(([v,l])=>btn(l,'scenario:'+v,scenario===v?'active':'',running?'disabled':'')).join('')}</div></div><div class="controls">${btn(running?'Ⅱ &nbsp; PAUSE':engine.t?'▷ &nbsp; RESUME ANALYSIS':'▷ &nbsp; START ANALYSIS','start','primary')}${btn('↺ &nbsp; RESET','reset','quiet')}<span class="simulation-note">Synthetic physiological demonstration · ${engine.scenarioLabel()}</span><span class="session mono">${engine.id?'SIMULATION '+engine.id:'READY TO BEGIN'} <b>${time(engine.t)}</b></span></div>`;}
function stats(){return `<div class="stats">${[['SIMULATED PATIENT STATE',engine.warning?'DIVERGING':engine.d>engine.criterion?'OBSERVING':'STABLE',engine.warning?'Persistent pattern shift':'Reference physiology'],['GEOMETRIC RISK INDEX',`${engine.risk}<small> / 100</small>`,'Prototype index · not a probability'],['GEODESIC DIVERGENCE',`<small>dR</small> ${f(engine.d,3)}`,'Distance from reference state'],['TREND',`${engine.rate>.025?'↗ INCREASING':engine.rate<-.025?'↘ DECREASING':'→ STABLE'}`,`${engine.history.length?f(engine.rate,3):'0.000'} / observation`],['OBSERVATION TIME',time(engine.t),running?'Analysis active':engine.t?'Analysis paused':'Awaiting analysis']].map((s,i)=>`<div class="stat" title="${i===1?'Prototype geometric risk index. Not a probability or clinically validated score.':'Computed from synthetic physiology'}"><label>${s[0]}</label><strong class="${i===0?'state-text':''}">${s[1]}</strong><span>${s[2]}</span></div>`).join('')}</div>`;}
function spark(values,width=130,height=32,color='var(--teal)'){const min=Math.min(...values),max=Math.max(...values),range=Math.max(max-min,.01),p=values.map((x,i)=>`${i*width/Math.max(values.length-1,1)},${height-3-(x-min)/range*(height-6)}`).join(' ');return `<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" class="spark" aria-hidden="true"><polyline points="${p}" fill="none" stroke="${color}" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg>`;}
function vitals(){return `<div class="section-label"><h2>LIVE PHYSIOLOGICAL SIGNALS</h2><span><i class="dot"></i> ${running?'RECEIVING SYNTHETIC OBSERVATIONS':'BASELINE LOADED'} &nbsp; · &nbsp; 8 VARIABLES</span></div><div class="vitals">${G.labels.map((l,i)=>`<div class="vital"><div><span>${l}</span><small>${i===6||i===7?'DERIVED':'SYNTHETIC'}</small></div><strong>${f(engine.vitals[i],[2,3].includes(i)?1:0)}<em>${G.units[i]}</em></strong>${spark(engine.raw.slice(-30).map(x=>x.v[i]))}<p>${G.names[i]}</p></div>`).join('')}</div><div class="process ${running?'processing':''}">${['Signals','Window','Covariance','SPD state','Distance','Trend'].map((x,i)=>`<span style="--delay:${i*.13}s"><i></i>${x}${i<5?'<b>›</b>':''}</span>`).join('')}<small>LOCAL GEOMETRY ENGINE</small></div>`;}
const point=(i,r,cx=210,cy=158,n=8)=>[cx+Math.sin(i*2*Math.PI/n)*r,cy-Math.cos(i*2*Math.PI/n)*r];
const poly=(r,cx=210,cy=158)=>r.map((x,i)=>point(i,x,cx,cy).join(',')).join(' ');
function radar(v=engine.vitals,only=false){const radii=v.map((x,i)=>G.clamp(73+(x-engine.mu[i])/engine.sd[i]*5,30,119));return `<svg class="radar" viewBox="0 0 420 315" role="img" aria-label="Normalized physiological profile compared with baseline">${[30,55,80,105,122].map(r=>`<polygon points="${poly(Array(8).fill(r))}" class="radar-grid"/>`).join('')}${G.labels.map((l,i)=>{const p=point(i,122),t=point(i,143);return `<path d="M210 158L${p.join(' ')}" class="radar-grid"/><text x="${t[0]}" y="${t[1]+4}" text-anchor="middle">${l}</text>`;}).join('')}<polygon points="${poly(Array(8).fill(73))}" class="reference-shape"/><polygon points="${poly(radii)}" class="current-shape"/>${radii.map((r,i)=>{const p=point(i,r);return `<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="var(--teal)"/>`;}).join('')}<circle cx="210" cy="158" r="3" fill="#66838c"/></svg>`;}
function profile(){const state=selectedTime===null?null:engine.states.find(s=>s.t===selectedTime),v=state?.v||engine.vitals;const similarity=Math.round(100*Math.exp(-v.reduce((s,x,i)=>s+((x-engine.mu[i])/engine.sd[i])**2,0)/160));return panel('Physiological geometry','An intuitive view of the multivariate profile',`${compare?`<div class="compare-radars"><div><label>REFERENCE</label>${radar(engine.mu)}</div><span>→</span><div><label>CURRENT</label>${radar(v)}</div></div>`:radar(v)}<div class="legend"><span><i class="legend-ref"></i>Reference physiology</span><span><i></i>Current physiology${state?' · '+time(state.t):''}</span></div><div class="profile-metrics"><div><label>PROFILE SIMILARITY</label><strong>${similarity}<small>%</small></strong></div><div><label>RELATIONSHIP SHIFT</label><strong>${engine.d>engine.criterion?'HIGH':engine.d>1.5?'MODERATE':'LOW'}</strong></div><div><label>GEODESIC DISTANCE</label><strong>${f(engine.d,3)}</strong></div></div><p class="caption">Normalized profile for interpretation. Mathematical distance is calculated from covariance SPD states.</p>`,btn(compare?'OVERLAY':'COMPARE STATES','compare','text-button')+btn('ⓘ','explain:profile','info'));}
function manifold(){function project(x,y){const a=rotation*.2,xx=x*Math.cos(a)-y*Math.sin(a),yy=x*Math.sin(a)+y*Math.cos(a);return [245+(xx-yy)*56*zoom,166+(xx+yy)*18*zoom-(.18*(x*x+y*y))*30*zoom];}const lines=[];for(let i=-4;i<=4;i+=.5){for(const axis of [0,1]){const ps=[];for(let j=-4;j<=4;j+=.2)ps.push(project(axis?j:i,axis?i:j).join(','));lines.push(`<polyline points="${ps.join(' ')}"/>`);}}
 const states=engine.states.filter((s,i,a)=>i%Math.max(1,Math.floor(a.length/18))===0||i===a.length-1),loc=s=>project(s.d*.65,Math.tanh((s.matrix[0][1]-engine.ref[0][1])*.3)*1.8);const pts=states.map(loc),ref=project(0,0),last=pts.at(-1)||ref;
 return panel('Advanced geometric view','Covariance states on an illustrative SPD surface',`<div class="manifold-wrap"><div class="manifold-label">SPD MANIFOLD <span>𝒮⁺₈</span></div><svg viewBox="0 0 490 315" class="manifold" role="img" aria-label="Illustrative projection of covariance trajectory"><defs><radialGradient id="surface"><stop stop-color="#205c60" stop-opacity=".18"/><stop offset="1" stop-color="#0c1722" stop-opacity="0"/></radialGradient></defs><ellipse cx="245" cy="163" rx="230" ry="140" fill="url(#surface)"/><g fill="none" stroke="#2c565e" stroke-width=".65" opacity=".65">${lines.join('')}</g><ellipse cx="${ref[0]}" cy="${ref[1]}" rx="42" ry="16" fill="#4aceba12" stroke="#54b9ab" stroke-dasharray="3 5"/><polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="var(--teal)" stroke-width="2.5"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${states[i].t===selectedTime?7:3}" fill="var(--teal)"/>`).join('')}<circle cx="${ref[0]}" cy="${ref[1]}" r="4" fill="#8b9ca9"/><text x="${ref[0]-33}" y="${ref[1]+32}">Σref</text><circle cx="${last[0]}" cy="${last[1]}" r="7" fill="var(--teal)" stroke="#102730" stroke-width="3"/><text x="${last[0]+14}" y="${last[1]-12}" fill="var(--teal)">Σt</text></svg><div class="manifold-tools">${btn('↶','rotate','tiny','aria-label="Rotate surface"')}${btn('+','zoom-in','tiny','aria-label="Zoom in"')}${btn('−','zoom-out','tiny','aria-label="Zoom out"')}${btn('↺','view-reset','tiny','aria-label="Reset view"')}</div></div><div class="trajectory">${engine.states.filter((s,i,a)=>i%Math.max(1,Math.ceil(a.length/5))===0).slice(-5).map(s=>btn(`● &nbsp; ${s.t===0?'T₀':s.t+'s'}`,'state:'+s.t,'text-button '+(s.t===selectedTime?'active':''))).join('')}${btn('● NOW','state:now','text-button')}</div><div class="distance-equation">d<sub>R</sub>(Σ<sub>ref</sub>, Σ<sub>t</sub>) <span>= ${f(engine.d,3)}</span></div><p class="caption">Illustrative 2D projection, not an isometric embedding or the computed geodesic. Position uses distance and HR–RR covariance change.</p>`,btn('EXPLAIN','explain:manifold','text-button'));}
function divergence(){const history=engine.history.length?[{t:0,d:0},...engine.history]:[{t:0,d:0}],max=Math.max(4,engine.criterion+1,...history.map(s=>s.d))*1.12,start=Math.max(0,engine.t-179),end=Math.max(90,engine.t),x=t=>42+(t-start)/(end-start)*1010,y=d=>170-d/max*145,ps=history.filter(s=>s.t>=start).map(s=>`${x(s.t)},${y(s.d)}`).join(' '),peak=engine.peak;return panel('Geometric divergence over time','Riemannian distance · simulation time',`<svg class="divergence" viewBox="0 0 1080 205" role="img" aria-label="Computed Riemannian distance over simulation time"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#64d4bf" stop-opacity=".2"/><stop offset="1" stop-color="#64d4bf" stop-opacity="0"/></linearGradient></defs><rect x="42" y="25" width="1010" height="${y(engine.criterion)-25}" fill="#d2a66306"/>${[0,1,2,3,4].map(i=>{const v=i*max/4;return `<path d="M42 ${y(v)}H1052" stroke="#21303c" stroke-dasharray="3 5"/><text x="12" y="${y(v)+4}">${f(v,1)}</text>`;}).join('')}<path d="M42 ${y(engine.criterion)}H1052" stroke="#b99a62" stroke-opacity=".65" stroke-dasharray="5 6"/><text x="1047" y="${y(engine.criterion)-8}" text-anchor="end" fill="#ba9a68">PROTOTYPE ELEVATED REGION</text><text x="1047" y="161" text-anchor="end">BASELINE / OBSERVATION</text><polygon points="${x(history.find(s=>s.t>=start)?.t||0)},170 ${ps} ${x(engine.t)},170" fill="url(#area)"/><polyline points="${ps}" fill="none" stroke="var(--teal)" stroke-width="2.4"/><circle cx="${x(engine.t)}" cy="${y(engine.d)}" r="4" fill="var(--teal)"/>${[0,1,2,3,4,5,6].map(i=>`<text x="${42+i*1010/6}" y="196" text-anchor="middle">${Math.round(start+(end-start)*i/6)}s</text>`).join('')}</svg><div class="chart-metrics">${[['CURRENT dR',f(engine.d,3)],['BASELINE MEAN',f(engine.baselineMean,3)],['DEVIATION',f(engine.d-engine.baselineMean,3)],['RATE / STEP',f(engine.rate,3)],['PERSISTENCE',Math.round(engine.persistence*100)+'%'],['SESSION PEAK',f(peak,3)]].map(x=>`<div><label>${x[0]}</label><b>${x[1]}</b></div>`).join('')}</div><p class="caption">Regions are prototype demonstration criteria, not clinical thresholds. Persistence uses the last 10 observations.</p>`,btn('EXPLAIN','explain:distance','text-button'));}
function changes(){return `<div class="changes">${engine.changes().slice(0,5).map(c=>`<div><span>${G.labels[c.i]} <small>↔</small> ${G.labels[c.j]}</span><div class="bar-track"><i style="width:${Math.min(100,Math.abs(c.value)/Math.max(.1,Math.abs(engine.changes()[0].value))*100)}%"></i></div><b>${c.value>=0?'+':''}${f(c.value)}</b></div>`).join('')}</div><p class="caption">Descriptive standardized covariance changes. Not causal attribution.</p>`;}
function network(matrix=engine.matrix,change=false){const c=change?G.correlation(matrix).map((r,i)=>r.map((v,j)=>v-G.correlation(engine.ref)[i][j])):G.correlation(matrix);return `<svg viewBox="0 0 420 310" class="network" role="img" aria-label="Correlation network">${c.flatMap((r,i)=>r.map((v,j)=>{if(j<=i||Math.abs(v)<.18)return '';const a=point(i,112,210,155),b=point(j,112,210,155);return `<path d="M${a}L${b}" stroke="${v<0?'#af987d':'#68cdbb'}" stroke-width="${Math.abs(v)*4}" opacity="${.15+Math.abs(v)*.65}"><title>${G.labels[i]} / ${G.labels[j]}: ${f(v,3)}</title></path>`;})).join('')}${G.labels.map((l,i)=>{const p=point(i,112,210,155);return `<circle cx="${p[0]}" cy="${p[1]}" r="21" fill="#14232e" stroke="#42606a"/><text x="${p[0]}" y="${p[1]+4}" text-anchor="middle">${l}</text>`;}).join('')}</svg><p class="caption">Teal: positive · sand: negative · thickness: |correlation|. Edges shown for |r| ≥ 0.18.</p>`;}
function networkPanel(){return `<div class="tabs">${['Baseline','Current','Change'].map(t=>btn(t,'network:'+t,networkMode===t?'active':'')).join('')}</div>${network(networkMode==='Baseline'?engine.ref:engine.matrix,networkMode==='Change')}${networkMode==='Change'?'<p class="caption">Change mode shows current minus baseline correlations. Edge color indicates the sign of the change.</p>':''}`;}
function heatmap(matrix){const max=Math.max(.1,...matrix.flat().map(Math.abs));return `<div class="heatmap" role="table" aria-label="Eight by eight physiological matrix"><span></span>${G.labels.map(l=>`<b>${l}</b>`).join('')}${matrix.map((r,i)=>`<b>${G.labels[i]}</b>${r.map((v,j)=>`<span role="cell" tabindex="0" title="${G.labels[i]} ↔ ${G.labels[j]}: ${f(v,5)}" style="background:${v<0?`rgba(175,140,106,${.08+Math.abs(v)/max*.65})`:`rgba(69,170,155,${.08+Math.abs(v)/max*.65})`}">${f(v)}</span>`).join('')}`).join('')}</div><div class="matrix-key"><span>− Negative</span><i></i><span>Positive +</span></div>`;}
function warning(){return engine.warning?`<div class="warning" role="status"><div><label>PROTOTYPE EARLY-WARNING CRITERION REACHED</label><h3>Physiological geometry shift detected.</h3><p>Persistent multivariate divergence detected. ${Math.round(engine.persistence*100)}% persistence · dR ${f(engine.d,3)}</p></div>${btn('WHY WAS THIS FLAGGED? ↗','explain:warning','amber')}</div>`:'';}
function story(){return `<div class="story"><span><b>01</b> PROFILE CHANGES</span><i>→</i><span><b>02</b> COVARIANCE STATE MOVES</span><i>→</i><span><b>03</b> DISTANCE QUANTIFIES CHANGE</span></div>`;}
function matrixContent(){const eig=G.eigen(engine.matrix).values.sort((a,b)=>b-a),base=matrixState==='Baseline'?engine.ref:matrixState==='Difference'?engine.matrix.map((r,i)=>r.map((v,j)=>v-engine.ref[i][j])):engine.matrix;if(matrixTab==='Correlation')return `${heatmap(matrixState==='Difference'?G.correlation(engine.matrix).map((r,i)=>r.map((v,j)=>v-G.correlation(engine.ref)[i][j])):G.correlation(base))}<p class="caption">Correlation rescales covariance from -1 to +1. Sand is negative, dark is near zero, teal is positive.</p>`;if(matrixTab==='Eigenvalues')return `<div class="spectrum compact">${eig.map((v,i)=>`<div><div style="height:${Math.max(2,v/eig[0]*180)}px"></div><b>λ${i+1}</b><span>${f(v,3)}</span></div>`).join('')}</div><div class="properties compact-props">${[['λmin',f(eig.at(-1),5)],['Condition number',f(eig[0]/eig.at(-1),2)],['SPD','VALID']].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div>`;if(matrixTab==='Geometry')return `<div class="properties">${[['Dimension','8 × 8'],['Symmetric','YES'],['Positive definite',eig.at(-1)>0?'YES':'NO'],['Min eigenvalue',f(eig.at(-1),5)],['Max eigenvalue',f(eig[0],5)],['Condition number',f(eig[0]/eig.at(-1),2)],['Regularization ε',G.EPS],['Current dR',f(engine.d,3)]].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div>`;return `<div class="tabs small-tabs">${['Current','Baseline','Difference'].map(t=>btn(t,'matrix-state:'+t,matrixState===t?'active':'')).join('')}</div>${heatmap(base)}<div class="equation secondary">Σt = Cov(Zt) + εI</div><p class="caption">Each matrix summarizes how the physiological signals vary together during the current observation window.</p>${btn('EXPLAIN','explain:covariance','text-button')}`;}
function compactMatrix(){return panel('Current physiological state','Relationships, made visible · 8 × 8',`<div class="tabs">${['Matrix','Correlation','Eigenvalues','Geometry'].map(t=>btn(t,'matrix-tab:'+t,matrixTab===t?'active':'')).join('')}</div>${matrixContent()}`,'','matrix-compact');}
function signalExplorer(){return panel('Live process','Signals → window → covariance → SPD → distance → trend',`<div class="tabs">${[0,1,2,3,6].map(i=>btn(G.labels[i],'signal:'+i,selectedSignals.includes(i)?'active':'')).join('')}<span class="push"></span>${btn(rawMode?'RAW UNITS':'NORMALIZED','raw','active')}</div><div class="signal-charts">${selectedSignals.map(i=>{const rows=engine.raw.slice(-90),vals=rows.map(r=>rawMode?r.v[i]:(r.v[i]-engine.mu[i])/engine.sd[i]);return `<div><label>${G.labels[i]} <small>${rawMode?G.units[i]:'baseline z-score'}</small></label>${spark(vals,850,65)}<span class="mono">${f(vals.at(-1))}<small> range ${f(Math.min(...vals))}…${f(Math.max(...vals))}</small></span></div>`;}).join('')}</div>`);}
function overview(){return `<section class="hero"><div><div class="eyebrow"><span></span> GEOMETRIC EARLY WARNING SYSTEM</div><h1>PHYSIOLOGY.<br><span>IN A NEW DIMENSION.</span></h1><p>Detecting changes in physiological relationships before<br class="desktop"> conventional thresholds tell the full story.</p></div><div class="hero-aside"><div class="orbit">${icon(2)}</div><label>A DIFFERENT PERSPECTIVE</label><p>Individual signals.<br>Connected insight.</p></div></section>${controls()}${stats()}${warning()}${vitals()}${signalExplorer()}<h2 class="major-section">THE GEOMETRY OF PHYSIOLOGY</h2><div class="two-col geometry-pair">${profile()}${manifold()}</div>${story()}${divergence()}<div class="two-col matrix-layout">${compactMatrix()}${panel('What changed most?','Largest off-diagonal covariance changes',changes(),btn('VIEW WHY ↗','explain:warning','text-button'))}</div>${warning()}<div class="two-col bottom-panels">${panel('Why not just use thresholds?','The research question',`<h4>Each value tells a story.<br><span>Together, they reveal a pattern.</span></h4><p>GeoSepsis asks whether the geometry of physiology is changing, even when single values remain plausible in isolation.</p><div class="inline-actions">${btn('EXPLORE THE GEOMETRY ↗','nav:Geometry','text-button')}${btn('COMPARE BASELINE ↔ NOW','baseline','text-button',engine.t<10?'disabled':'')}</div>`)}${panel('How it works','Local exhibition pipeline',flow(['Synthetic subject generation','Temporal physiological observations','36-observation window','Covariance + εI','SPD eigen verification','Affine-invariant distance','Persistence-gated prototype warning']))}</div><div class="event-preview"><i class="dot"></i><span class="mono">${time(engine.events[0].t)}</span> ${engine.events[0].message}<span class="push">${btn('CAPTURE STATE','capture','text-button')} ${snapshot?btn('VIEW SNAPSHOT','snapshot','text-button'):''}</span></div>`;}
function monitor(){return `${pageHead('Live monitor','The current physiological picture.','SYNTHETIC OBSERVATIONS')}${controls()}${stats()}${warning()}${vitals()}${panel('Physiological signals','Aligned scales for honest comparison',`<div class="tabs">${[0,1,2,3,6].map(i=>btn(G.labels[i],'signal:'+i,selectedSignals.includes(i)?'active':'')).join('')}<span class="push"></span>${btn(rawMode?'RAW UNITS':'NORMALIZED','raw','active')}</div><div class="signal-charts">${selectedSignals.map(i=>{const rows=engine.raw.slice(-90),vals=rows.map(r=>rawMode?r.v[i]:(r.v[i]-engine.mu[i])/engine.sd[i]);return `<div><label>${G.labels[i]} <small>${rawMode?G.units[i]:'baseline z-score'}</small></label>${spark(vals,850,65)}<span class="mono">${f(vals.at(-1))}<small> range ${f(Math.min(...vals))}…${f(Math.max(...vals))}</small></span></div>`;}).join('')}</div><p class="caption">Each row has its own vertical range. Horizontal span: ${engine.raw.slice(-90)[0].t}s to ${engine.t}s; negative times are synthetic preloaded baseline.</p>`)}${panel('From signals to geometry','Accelerated exhibition window',`<div class="window-strip">${Array.from({length:60},(_,i)=>`<i class="${i>=24?'selected':''}" style="height:${16+(i*13%29)}px"></i>`).join('')}</div><div class="research-metrics"><div><b>36</b><span>synthetic observations</span></div><div><b>6 h</b><span>conceptual window</span></div><div><b>1 h</b><span>historical research stride</span></div></div><p>One exhibition second produces one synthetic 10-minute observation. Geometry updates every observation; the research pipeline uses hourly data and a 1-hour stride. No real clinical time is being observed.</p>`)}${divergence()}${panel('Event log','Meaningful changes during this local session',engine.events.map(e=>`<div class="log"><span class="mono">${time(e.t)}</span>${e.message}</div>`).join(''))}`;}
function pageHead(title,sub,eyebrow='GEOSEPSIS / RESEARCH PLATFORM'){return `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>`;}
function geometry(){return `${pageHead('The shape of change.','From physiological relationships to a measurable geometric distance.') }<div class="two-col">${profile()}${manifold()}</div>${story()}<div class="two-col">${panel('Physiological relationship network','Connections derived from physiological correlations',networkPanel())}${panel('Riemannian distance','Affine-invariant distance between SPD states',`<div class="equation">d<sub>R</sub>(A,B) = ‖ log(A<sup>−½</sup>BA<sup>−½</sup>) ‖<sub>F</sub></div><div class="equation secondary">= √(∑ᵢ log² λᵢ) = <b>${f(engine.d,3)}</b></div><p>The equation measures how much the current pattern of physiological relationships differs from the reference, while respecting covariance geometry.</p><div class="symbol-grid">${['dR','A','B','A⁻½','log( )','‖ · ‖F','λᵢ','∑ᵢ'].map(s=>btn(s,'symbol:'+s,'symbol')).join('')}</div>${btn('▷ SHOW ME','equation','text-button')}`)}</div><div class="two-col">${panel('A mathematically stable state','Symmetric positive definite',`<div class="equation">Σt = Cov(Zt) + εI</div><p>We measure how standardized signals vary together and add ε = ${G.EPS} to the diagonal. MAP and PP depend on SBP and DBP, so regularization is necessary to make the covariance positive definite.</p><p>SPD states support inverse square roots, matrix logarithms, and geodesic distance.</p>`,btn('EXPLAIN','explain:covariance','text-button'))}${panel('Reference physiology','Estimated from synthetic baseline observations',`<div class="equation">Σref ← 720 baseline observations</div><p>The exhibition uses a regularized covariance estimated from a synthetic baseline. Its means and standard deviations remain fixed throughout the session.</p><div class="equation secondary">Research concept: argmin<sub>Σ</sub> ∑ᵢ d²<sub>R</sub>(Σ, Σᵢ)</div><p>This Fréchet mean is a possible research reference: the state minimizing total squared geometric distance. It is not the exhibition estimator.</p>`)}</div>${divergence()}`;}
function matrices(){const eig=G.eigen(engine.matrix).values.sort((a,b)=>a-b),base=matrixState==='Baseline'?engine.ref:matrixState==='Difference'?engine.matrix.map((r,i)=>r.map((v,j)=>v-engine.ref[i][j])):engine.matrix;let content=heatmap(matrixTab==='Correlation'?(matrixState==='Difference'?G.correlation(engine.matrix).map((r,i)=>r.map((v,j)=>v-G.correlation(engine.ref)[i][j])):G.correlation(base)):base);
 if(matrixTab==='Eigenvalues')content=`<div class="spectrum">${eig.map((v,i)=>`<div><div style="height:${Math.max(2,v/eig.at(-1)*210)}px"></div><b>λ${i+1}</b><span>${f(v,3)}</span></div>`).join('')}</div><p>Current covariance eigenvalues summarize variation along principal geometric directions; they are not biological attributions.</p>`;
 if(matrixTab==='Properties')content=`<div class="properties">${[['Dimension','8 × 8'],['Symmetric',engine.matrix.every((r,i)=>r.every((v,j)=>Math.abs(v-engine.matrix[j][i])<1e-9))?'YES':'NO'],['Positive definite',eig[0]>0?'YES':'NO'],['Minimum eigenvalue',f(eig[0],5)],['Maximum eigenvalue',f(eig.at(-1),5)],['Condition number',f(eig.at(-1)/eig[0],2)],['Regularization ε',G.EPS],['Window size',G.WINDOW+' observations']].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div>`;
 return `${pageHead('Relationships, revealed.','Inspect the actual matrices behind the geometric signal.')}<div class="two-col matrix-layout">${panel('Covariance state','Baseline-standardized physiological variables',`<div class="tabs">${['Covariance','Correlation','Eigenvalues','Properties'].map(t=>btn(t,'matrix-tab:'+t,matrixTab===t?'active':'')).join('')}</div>${['Covariance','Correlation'].includes(matrixTab)?`<div class="tabs small-tabs">${['Baseline','Current','Difference'].map(t=>btn(t,'matrix-state:'+t,matrixState===t?'active':'')).join('')}</div>`:''}${content}`)}<div>${panel('Top changed relationships','ΔΣ = Σcurrent − Σreference',changes())}${panel('Reading the matrix','One cell. One relationship.',`<p>Rows and columns represent the same eight variables. Off-diagonal cells show how pairs vary together; diagonal cells measure variance.</p><p>Hover or focus a cell to inspect its exact value. A difference matrix highlights departure from reference.</p><p>Correlation rescales each covariance by the two standard deviations.</p>`,btn('EXPLAIN COVARIANCE','explain:covariance','text-button'))}</div></div>`;}
function metrics(items){return `<div class="research-metrics">${items.map(([v,l])=>`<div><b>${v}</b><span>${l}</span></div>`).join('')}</div>`;}
function flow(items){return `<div class="flow">${items.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${s}</b></div>`).join('')}</div>`;}
function research(){return `${pageHead('Evidence & development.','A research direction. An honest account.')}<div class="research-callout"><label>THE RESEARCH QUESTION</label><h2>Can the geometry of physiological relationships provide useful early-warning information?</h2><p>Hypothesis: deterioration may alter relationships among signals before isolated variables become strongly abnormal, producing measurable divergence.</p></div>${panel('Preliminary PhysioNet / CinC 2019 analysis','Project-reported preliminary retrospective results',`${metrics([['~0.621','GeoSepsis AUROC'],['~0.559','Comparator AUROC'],['~0.14','Preliminary AUPRC'],['~25 h','Observed pre-event divergence'],['p < 0.001','Reported statistical result']])}<div class="tags">${tag('PRELIMINARY')}${tag('RETROSPECTIVE')}${tag('NOT CLINICAL VALIDATION','sand')}</div><p>Project-reported figures supplied with this prototype brief, not independently reproduced here. These findings do not establish prospective clinical effectiveness. Cohort definitions, confidence intervals, comparator specification, and statistical protocol require supporting research documentation.</p>`)}${panel('eICU demonstration pipeline','Research / demonstration · not prospective clinical validation',`${metrics([['2,520','ICU stays'],['327','Septic stays'],['1,766','Training stays'],['754','Test stays']])}${flow(['Raw ICU data','Hourly resampling','6-hour windows · 1-hour stride','8 physiological variables','SPD covariance','Riemannian features','Logistic regression / MLP exploration'])}`)}${panel('The research journey','An evolving investigation',flow(['Problem','Hypothesis','PhysioNet exploration','Geometric divergence','eICU replication / demonstration','Physical prototype','Future prospective validation']))}`;}
function architecture(){return `${pageHead('From acquisition to insight.','Designed as a low-cost edge research platform.')}<div class="two-col">${panel('Exhibition data path','Fully local · currently implemented',flow(['SimulationDataSource','Correlated physiological observations','Fixed baseline standardization','36-observation temporal buffer','Covariance + εI','SPD verification / eigendecomposition','Affine-invariant distance','Rate / persistence / prototype index','GeoSepsis dashboard']))}${panel('Physical research architecture','Proposed acquisition path',`${flow(['MAX30102 · HR + SpO₂ candidate','Additional physiological inputs','Raspberry Pi 5 · local processing','Display · visualization / interaction'])}<p>The browser does not verify connected hardware. MAX30102DataSource is an extension point requiring an acquisition bridge, signal-quality checks, and device validation. All present dashboard values are synthetic.</p><div class="hardware"><span>${icon(5)}</span><div><h4>Small footprint.<br>Local computation.</h4><p>No cloud, authentication, analytics, or remote runtime assets.</p></div></div>`)}</div>${panel('The software engine','Numerically explicit and inspectable',`<p>Vanilla JavaScript, SVG, and CSS. One calculation per second, bounded histories, and 8 × 8 Jacobi eigendecomposition. The static production build runs from a loopback server on port 3000. Raspberry Pi setup and kiosk startup are included in README.md.</p>`)}`;}
function impact(){return `${pageHead('Why earlier recognition matters.','A research vision for additional clinical context.')}<div class="research-callout"><label>THE INTENDED OPPORTUNITY</label><h2>The goal is to give clinicians<br>more time.</h2><p>GeoSepsis explores whether changing multivariate relationships could provide useful additional warning for clinical assessment. This prototype does not demonstrate earlier treatment or improved patient outcomes.</p></div><div class="two-col">${panel('Current monitoring concept','Individual measurements',flow(['Individual abnormalities','Recognizable deterioration','Clinical review']))}${panel('GeoSepsis research vision','Additional information from relationships',flow(['Changing physiological relationships','Geometric divergence','Additional early-warning information','Earlier clinical review opportunity']))}</div><div class="four-col">${[['Multivariate','Analyzes relationships among signals.'],['Geometric','Represents covariance using SPD geometry.'],['Temporal','Tracks evolving physiological relationships.'],['Edge-capable','Designed for Raspberry Pi-class computing.']].map(([t,s])=>panel(t,'',`<p>${s}</p>`)).join('')}</div>${panel('Research novelty being explored','Designed for further validation and intellectual-property evaluation',`<p>The integration of temporal physiological covariance states, Riemannian divergence, early-warning visualization, and low-cost edge acquisition into a sepsis-oriented research prototype.</p><p>Formal patentability requires dedicated prior-art and intellectual-property assessment. Prospective clinical validation is required.</p>`)}`;}
function about(){return `${pageHead('A different way to see physiology.','GeoSepsis · Geometric Early Warning System') }<div class="research-callout"><label>WHAT IS GEOSEPSIS?</label><h2>Sense. Relate. Map.<br>Track. Measure. Warn.</h2><p>A research prototype investigating geometry-based analysis of multivariate physiological changes associated with sepsis and clinical deterioration.</p></div>${panel('Research status','Transparent by design',`<div class="properties">${[['Exhibition data','Synthetic physiological demonstration'],['Research','Retrospective exploration'],['Clinical validation','Prospective validation required'],['Device status','Not a diagnostic medical device'],['Privacy','Local session only · no personal records'],['Session behavior','Refresh starts fresh']].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div>`)}${panel('Exhibition controls','For presenters',`<p><kbd>S</kbd> Start / pause &nbsp; <kbd>R</kbd> Reset &nbsp; <kbd>Esc</kbd> Close explanation / leave fullscreen.</p><p>Exhibition lock prompts before browser navigation or refresh where the browser permits. Browser kiosk policies may override this prompt; staff can exit through Chromium controls.</p>${btn(locked?'DISABLE EXHIBITION LOCK':'ENABLE EXHIBITION LOCK','lock','quiet')}`)}`;}
function render(){const scroll=window.scrollY;mount(`<aside class="sidebar"><a class="brand" href="#Overview" aria-label="GeoSepsis overview"><img src="./favicon.svg" alt=""><div>GEOSEPSIS<small>RESEARCH PLATFORM</small></div></a><div class="nav-label">WORKSPACE</div><nav>${pages.map((p,i)=>`<button aria-label="${p}" data-action="nav:${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${p}</span>${page===p?'<i></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-status"><i class="dot"></i><span>LOCAL COMPUTATION<small>All data stays on this device</small></span></div>${btn(icon(7)+'<span>System health</span>','explain:health','health-button')}<div class="version"><span>v1.1</span>Research Prototype</div></div></aside><main><header><div><b>${page}</b><span class="header-divider">/</span><span>Geometric Early Warning System</span></div><div class="header-status"><span class="prototype">RESEARCH PROTOTYPE</span><span class="mode"><i class="dot"></i> SIMULATION MODE</span>${btn('⛶','fullscreen','tiny','aria-label="Toggle fullscreen"')}</div></header><div class="content ${engine.warning?'is-warning':''}">${({Overview:overview,Geometry:geometry,Research:research,'System Architecture':architecture,Impact:impact,About:about}[page])()}</div><footer><span>GEOSEPSIS <b>·</b> Geometry-based physiological early-warning research</span><span>REQUIRES PROSPECTIVE CLINICAL VALIDATION</span></footer></main>`);window.scrollTo(0,scroll);}
const explanations={profile:['Physiological geometry','The shape makes changes in the overall profile easy to see. It compares each value with the same fixed baseline.','Each radius is 73 + 5z, clipped to 30–119 display units; z uses fixed baseline means and standard deviations. Profile similarity is 100 exp(−Σz²/160), an illustrative score. This polygon is not the SPD manifold.'],manifold:['Covariance in geometric space','Each point represents a relationship pattern. As that pattern changes, the current point moves away from the reference.','The surface is an illustrative projection of the 36-dimensional space of symmetric 8 × 8 matrices. Coordinates derive from dR and HR–RR covariance change. Displayed paths are not exact geodesics; dR itself is the computed affine-invariant distance.'],distance:['Measuring geometric change','How different is the current relationship pattern from the reference pattern?','Compute A⁻½ with a symmetric eigendecomposition, form C = A⁻½BA⁻½, then calculate √Σlog²λᵢ. Baseline scaling is fixed. Distance is not a diagnosis or a probability.'],covariance:['How signals change together','Positive covariance means signals tend to move together. Negative covariance means they tend to move in opposite directions.','The unbiased sample covariance of 36 baseline-standardized observations is regularized with εI, ε = 0.08. Derived MAP and PP create linear dependence; regularization ensures positive definiteness.'],warning:['Why the prototype flags a state','A warning requires geometric distance to stay elevated across several recent observations. A single noisy window is not enough.','Criterion = max(2.5, 2.4 × baseline-window mean distance). A warning requires current dR above the criterion and at least 8 of the last 10 observations elevated. Risk = 100 × sigmoid(1.1dR + 2max(0,rate) + 1.8persistence − 4.4). These demonstration choices are not clinically validated.'],health:['System health','The simulation and geometry engine run locally.','SPD validation checks the actual eigenvalues of the current covariance. No sensor connectivity or render-performance claim is inferred.']};
const symbols={'dR':'Affine-invariant Riemannian distance: how geometrically different are these covariance states?','A':'Reference SPD covariance matrix: the baseline relationship pattern.','B':'Current SPD covariance matrix: the relationship pattern now.','A⁻½':'Inverse matrix square root: expresses the comparison relative to the reference geometry.','log( )':'Matrix logarithm: converts relative stretches into a measurable form.','‖ · ‖F':'Frobenius norm: combines all squared matrix entries into one magnitude.','λᵢ':'Eigenvalues of A⁻½BA⁻½: relative stretches or contractions.','∑ᵢ':'Sum over the eight geometric dimensions.'};
function relationshipComparison(){const a=G.correlation(engine.ref),b=G.correlation(engine.matrix);return `<h3>Baseline relationships → current</h3><div class="relationship-comparison">${engine.changes().slice(0,4).map(c=>`<div><b>${G.labels[c.i]} ↔ ${G.labels[c.j]}</b><span>r ${f(a[c.i][c.j])} → ${f(b[c.i][c.j])}</span><small>${b[c.i][c.j]>=0?'Positive':'Inverse'} current association</small></div>`).join('')}</div><p>Combined relationship changes alter the covariance state. This describes association, not causation. A pattern would warrant clinical review in a future validated implementation.</p>`;}
function openDrawer(title,body){const d=document.getElementById('drawer');if(!d.open)previousFocus=document.activeElement;d.innerHTML=`<div class="drawer-header"><label>GEOSEPSIS / EXPLAIN</label>${btn('×','close','close','aria-label="Close explanation"')}</div><h2>${title}</h2>${body}`;if(!d.open)d.showModal();}
function explain(kind){drawerKind=kind;const e=explanations[kind];openDrawer(e[0],`<div class="explain-block"><label>SIMPLE</label><p>${e[1]}</p></div><details open><summary>TECHNICAL</summary><p>${e[2]}</p></details>${kind==='warning'?`<div class="explain-block"><label>STATE AT ${time(engine.t)}</label><h3>${engine.warning?'Criterion reached':'Criterion not currently reached'}</h3><p>dR ${f(engine.d,3)} / criterion ${f(engine.criterion,3)} · persistence ${Math.round(engine.persistence*100)}% · risk ${engine.risk}/100</p>${changes()}${relationshipComparison()}<h3>How we got here</h3>${engine.events.slice().reverse().map(e=>`<div class="log"><span>${time(e.t)}</span>${e.message}</div>`).join('')}</div>`:kind==='health'?`<div class="properties">${[['Geometry engine','READY'],['SPD validation',G.eigen(engine.matrix).values.every(v=>v>0)?'PASS':'FAIL'],['Simulation engine',running?'ACTIVE':'READY / PAUSED'],['Data mode','SYNTHETIC'],['Bounded history',engine.history.length+' / 180'],['Local storage','NONE']].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div>`:''}`);}
function comparison(saved){const a=saved||engine.baselineState;openDrawer(saved?'Captured state → current':'Baseline → current',`<p>${engine.id||'No simulation ID'} · comparison captured at ${time(engine.t)}</p><div class="compare-radars"><div><label>${saved?'CAPTURE '+time(a.t):'REFERENCE'}</label>${radar(a.v)}</div><div><label>CURRENT ${time(engine.t)}</label>${radar()}</div></div><div class="distance-equation">dR between these states = ${f(G.distance(a.matrix,engine.matrix),3)}</div><div class="comparison-values">${G.labels.map((l,i)=>`<div><b>${l}</b><span>${f(a.v[i],1)} → ${f(engine.vitals[i],1)} ${G.units[i]}</span></div>`).join('')}<div><b>Risk index</b><span>${a.risk} → ${engine.risk} / 100</span></div></div><h3>Covariance: before</h3>${heatmap(a.matrix)}<h3>Covariance: now</h3>${heatmap(engine.matrix)}<h3>Relationships: before</h3>${network(a.matrix)}<h3>Relationships: now</h3>${network()}`);}
function reset(){running=false;engine=new G.Engine(Math.random,scenario);snapshot=null;selectedTime=null;compare=false;rotation=0;zoom=1;clearInterval(eqTimer);document.getElementById('drawer').close();render();}
function act(action){const [a,...tail]=action.split(':'),v=tail.join(':');switch(a){case 'nav':if(pages.includes(v)){page=v;selectedTime=null;history.replaceState(null,'','#'+encodeURIComponent(v));render();window.scrollTo(0,0);}return;case 'scenario':if(!running){scenario=v;reset();}return;case 'start':running=!running;if(running)engine.start();break;case 'reset':reset();return;case 'compare':compare=!compare;break;case 'explain':explain(v);return;case 'close':document.getElementById('drawer').close();clearInterval(eqTimer);previousFocus?.focus();return;case 'capture':snapshot={...engine.states.at(-1),id:engine.id};engine.log('Geometry snapshot captured');comparison(snapshot);break;case 'snapshot':comparison(snapshot);return;case 'baseline':comparison();return;case 'state':selectedTime=v==='now'?null:Number(v);break;case 'rotate':rotation++;break;case 'zoom-in':zoom=Math.min(1.8,zoom+.12);break;case 'zoom-out':zoom=Math.max(.55,zoom-.12);break;case 'view-reset':rotation=0;zoom=1;break;case 'matrix-tab':matrixTab=v;break;case 'matrix-state':matrixState=v;break;case 'raw':rawMode=!rawMode;break;case 'network':networkMode=v;break;case 'signal':selectedSignals=selectedSignals.includes(+v)?selectedSignals.filter(i=>i!==+v):[...selectedSignals,+v].sort((a,b)=>a-b);break;case 'symbol':openDrawer(v,`<p>${symbols[v]}</p>`);return;case 'equation':{clearInterval(eqTimer);eqStep=0;const val=f(engine.d,3);const stages=['A · reference matrix + B · current matrix','A⁻½ B A⁻½ · relative transformation','log(C) · matrix logarithm','‖log(C)‖F · magnitude',`dR = ${val}`];const show=()=>openDrawer('The equation, step by step',`<div class="equation-steps">${stages.map((s,i)=>`<div class="${i<=eqStep?'shown':''}"><span>0${i+1}</span>${s}</div>`).join('')}</div><p>Calculated state at ${time(engine.t)}. The animation explains the operations; the distance is already computed.</p>`);show();eqTimer=setInterval(()=>{eqStep++;show();if(eqStep>=4)clearInterval(eqTimer);},1000);return;}case 'lock':locked=!locked;break;case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>openDrawer('Fullscreen','<p>Use your browser fullscreen control or the Raspberry Pi kiosk script.</p>'));return;}render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)act(b.dataset.action);});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.manifold-wrap'))return;drag={x:e.clientX,y:e.clientY,rotation,zoom};e.target.closest('.manifold-wrap').setPointerCapture?.(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag)return;rotation=drag.rotation+(e.clientX-drag.x)/42;render();});
document.addEventListener('pointerup',()=>drag=null);
document.addEventListener('wheel',e=>{if(!e.target.closest('.manifold-wrap'))return;e.preventDefault();zoom=G.clamp(zoom+(e.deltaY<0?.08:-.08),.55,1.8);render();},{passive:false});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable]')||document.getElementById('drawer').open)return;if(e.key.toLowerCase()==='s'){e.preventDefault();act('start');}if(e.key.toLowerCase()==='r'){e.preventDefault();reset();}});
window.addEventListener('beforeunload',e=>{if(locked){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{const p=decodeURIComponent(location.hash.slice(1));if(pages.includes(p)){page=p;render();}});
document.getElementById('drawer').addEventListener('close',()=>clearInterval(eqTimer));
const initial=decodeURIComponent(location.hash.slice(1));if(pages.includes(initial))page=initial;render();
setInterval(()=>{if(!running)return;try{engine.step();const active=document.activeElement?.dataset.action;render();if(active){const el=[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===active);el?.focus({preventScroll:true});}}catch(error){console.error('Geometry calculation failed',error);running=false;engine=new G.Engine(Math.random,scenario);engine.log('Geometry state recalibrated.');snapshot=null;selectedTime=null;render();}},1000);
